<?php
use SweepLine\BeamIntersections;
$stub=BeamIntersections::clip([[0,0],[50,0],[50,200]]);
check(count($stub)===3&&abs($stub[2][1]-132.88)<0.000001,'Intersection stubs follow bends and stop at 600 feet of actual road length');
check(BeamIntersections::clip([[0,0],[0,0],[10,0]])===[[0,0],[10,0]],'Intersection clipping ignores duplicate vertices');
check(BeamIntersections::clip([[0,0]])===[],'Degenerate intersection branch cannot produce a decal');
$context=['branches'=>[['points'=>[[100,100],[100,300]],'width_m'=>8]]];
$contextRaster=new SweepLine\BeamRaster(8,400,str_repeat(pack('g',100),64),str_repeat(chr(100),192));
$contextObjects=BeamIntersections::objects($context,$contextRaster,[0,0,400,400],50,'test_context');
check(count($contextObjects)===1&&$contextObjects[0]['class']==='DecalRoad'&&!$contextObjects[0]['overObjects']&&$contextObjects[0]['hiddenInNavi'],'Small junction aprons use terrain decals without overlapping pavement collision meshes');
check($contextObjects[0]['nodes'][0]==[100,100,50,8],'Context decals use local coordinates and terrain elevation');
$contextGeometry=new SweepLine\BeamScenery([[0,100],[400,100]],array_fill(0,2,['width_m'=>8]),BeamIntersections::exclusions($context,[0,0,400,400]));
check(!$contextGeometry->allows(100,140,2)&&$contextGeometry->allows(140,140,2),'Trees and buildings avoid side-road stubs while retaining the selected-road scenery range');
check(SweepLine\BeamVegetation::choose('rock',[-85,40],200,3,0.5)===null,'Midwest exports exclude Utah boulders even on gray aerial patches');
check(SweepLine\BeamVegetation::choose('rock',[-110,38],1500,2,0.5,['canopy_evidence'=>0.1,'tree_probability'=>0.1])==='utah_rock','Dry bare western terrain can use Utah boulders');
check(SweepLine\BeamVegetation::choose('rock',[-119,39],2000,0,0.5,['canopy_evidence'=>0.9,'tree_probability'=>0.8])===null,'Green forested western terrain does not inherit desert boulders');

$meshProfile=SweepLine\BeamLanes::infer(['lanes'=>'2','width'=>'8'],'secondary',0);
$mainIntersectionRoad=[[0,100,50.25],[100,100,50.25],[400,100,50.25]];
$mainIntersectionProfiles=array_fill(0,3,$meshProfile);
$prepared=BeamIntersections::prepare($context,$mainIntersectionRoad,$mainIntersectionProfiles,$contextRaster,[0,0,400,400],50,[],static fn($m)=>null);
check(count($prepared['roads'])===1&&abs($prepared['roads'][0]['points'][0][2]-50.25)<0.00001,'Side-road surface starts at matching main-road elevation');
check($prepared['roads'][0]['points'][0][1]>104&&$prepared['roads'][0]['profiles'][0]['unmarked'],'Branch mesh begins outside main pavement with no entrance stripes');
$marked=BeamIntersections::markJunctions($mainIntersectionRoad,$mainIntersectionProfiles,$prepared['junctions']);
check(!empty($marked[1]['unmarked'])&&empty($marked[0]['unmarked'])&&empty($marked[2]['unmarked']),'Junction suppression removes markings locally while retaining distant road lines');
$excludedBridge=BeamIntersections::prepare($context,$mainIntersectionRoad,$mainIntersectionProfiles,$contextRaster,[0,0,400,400],50,[['start_m'=>90,'end_m'=>110]],static fn($m)=>null);
check($excludedBridge['roads']===[]&&$excludedBridge['skipped']===1,'Bridge interiors cannot acquire ground-level intersection branches');
$blank=imagecreatefromstring(SweepLine\BeamPng::road($meshProfile+['unmarked'=>true]));
check((imagecolorat($blank,0,0)&0xffffff)!==0xebebe1&&(imagecolorat($blank,128,0)&0xffffff)!==0xebbe23,'Unmarked junction asphalt contains neither white edges nor yellow center stripe');
$forestContext=['canopy_evidence'=>0.9,'edge_distance_m'=>30,'montane'=>0,'pine_probability'=>0.25];
check(SweepLine\BeamVegetation::choose('tree',[-85,40],250,0,0.2,$forestContext)==='beech_forest'&&SweepLine\BeamVegetation::choose('tree',[-85,40],250,0,0.8,$forestContext)==='beech_group','Dense eastern woodland interiors select purpose-made stock forest assets');
$forestContext['edge_distance_m']=5;
check(SweepLine\BeamVegetation::choose('tree',[-85,40],250,0,0.2,$forestContext)==='beech_b','Roadside trees retain individual models instead of interior groups');
